'use strict';

// MODULES //

var contains = require( '@stdlib/array/base/assert/contains' );
var symbol2alias = require( '@stdlib/plot/base/symbol2alias' );


// VARIABLES //

// List of symbols which lack a "face".
var EDGE_SYMBOLS = [
	'asterisk',
	'cross',
	'line',
	'stroke',
	'x'
];


// MAIN //

/**
* Tests whether a symbol lacks a "face" and is thus drawn entirely from its edge.
*
* @private
* @param {string} symbol - symbol alias or shorthand
* @returns {boolean} boolean indicating whether a symbol lacks a face
*
* @example
* var bool = isEdgeSymbol( 'x' );
* // returns true
*
* bool = isEdgeSymbol( 'o' );
* // returns false
*/
function isEdgeSymbol( symbol ) {
	return contains( EDGE_SYMBOLS, symbol2alias( symbol ) );
}


// EXPORTS //

module.exports = isEdgeSymbol;
